/* Returns the parking fee in dollars for a stay of the given number of minutes. */
double parkingFee(int minutes) {
    int extra;
    if (minutes <= 30)
        return 0.0;
    if (minutes <= 120)
        return 4.00;
    extra = (minutes - 120 + 29) / 30;
    return 4.00 + extra * 1.75;
}

