/* Returns the digital root of n (n >= 0). */
int digitalRoot(int n) {
    int sum;
    while (n >= 10) {
        sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        n = sum;
    }
    return n;
}

