#include <stdio.h>
#define MIN_SIZE 1
#define MAX_SIZE 20

int getInRange(int min, int max);
void drawEdge(int width);
void drawMiddle(int width);

int main(void) {
    int width, height, row;
    printf("Width:\n");
    width = getInRange(MIN_SIZE, MAX_SIZE);
    printf("Height:\n");
    height = getInRange(MIN_SIZE, MAX_SIZE);
    for (row = 1; row <= height; row++) {
        if (row == 1 || row == height)
            drawEdge(width);
        else
            drawMiddle(width);
    }
    return 0;
}

/* Repeatedly prompts until an integer in [min, max] is entered; returns it. */
int getInRange(int min, int max) {
    int value;
    printf("Enter a value (%d-%d): ", min, max);
    scanf("%d", &value);
    while (value < min || value > max) {
        printf("Error: value must be between %d and %d.\n", min, max);
        printf("Enter a value (%d-%d): ", min, max);
        scanf("%d", &value);
    }
    return value;
}

/* Prints a full row of '#' of the given width. */
void drawEdge(int width) {
    int i;
    for (i = 0; i < width; i++)
        printf("#");
    printf("\n");
}

/* Prints '#', then spaces, then '#' (a single '#' if width is 1). */
void drawMiddle(int width) {
    int i;
    printf("#");
    for (i = 2; i < width; i++)
        printf(" ");
    if (width > 1)
        printf("#");
    printf("\n");
}

